```rust
#[derive(Debug, PartialEq, Eq)]
pub enum Error {
    NotEnoughPinsLeft,
    GameComplete,
}

pub struct BowlingGame {
    rolls: Vec<u16>,
    frame: usize,
    pins_down: u16,
    tenth_rolls: usize,
    completed: bool,
}

impl BowlingGame {
    pub fn new() -> Self {
        Self {
            rolls: Vec::new(),
            frame: 0,
            pins_down: 0,
            tenth_rolls: 0,
            completed: false,
        }
    }

    pub fn roll(&mut self, pins: u16) -> Result<(), Error> {
        if self.completed {
            return Err(Error::GameComplete);
        }

        if self.frame < 9 {
            // Frames 1-9
            if self.pins_down + pins > 10 {
                return Err(Error::NotEnoughPinsLeft);
            }
            self.pins_down += pins;
            self.rolls.push(pins);
            if self.pins_down == 10 {
                self.frame += 1;
                self.pins_down = 0;
            }
        } else {
            // Frame 10
            if self.pins_down + pins > 10 {
                return Err(Error::NotEnoughPinsLeft);
            }
            self.pins_down += pins;
            self.rolls.push(pins);
            self.tenth_rolls += 1;
            if self.pins_down == 10 {
                self.pins_down = 0;
            }
            // Determine completion
            let first = self.rolls[self.rolls.len() - self.tenth_rolls];
            let strike_first = first == 10;
            if self.tenth_rolls == 2 {
                if !strike_first {
                    let second = self.rolls[self.rolls.len() - 1];
                    if first + second < 10 {
                        self.completed = true;
                    }
                }
            } else if self.tenth_rolls >= 3 {
                self.completed = true;
            }
        }

        Ok(())
    }

    pub fn score(&self) -> Option<u16> {
        if !self.completed {
            return None;
        }
        let mut score = 0u16;
        let mut i = 0;
        for _ in 0..10 {
            if i >= self.rolls.len() {
                break;
            }
            if self.rolls[i] == 10 {
                score += 10 + self.rolls[i + 1] + self.rolls[i + 2];
                i += 1;
            } else if self.rolls[i] + self.rolls[i + 1] == 10 {
                score += 10 + self.rolls[i + 2];
                i += 2;
            } else {
                score += self.rolls[i] + self.rolls[i + 1];
                i += 2;
            }
        }
        Some(score)
    }
}
